minInt(Int a, Int b): Int {
    if (a < b) {
        return a
    }
    return b
}

spaces(Int n): String {
    var out = ""
    var i = 0
    while (i < n) {
        out = out + "    "
        i++
    }
    return out
}

trimLine(String s): String {
    var start = 0
    var end = s.length()
    while (start < end) {
        var c = s.substring(start, start + 1)
        if (c == " " || c == "\t") {
            start++
        } else {
            break
        }
    }
    while (end > start) {
        var c = s.substring(end - 1, end)
        if (c == " " || c == "\t") {
            end = end - 1
        } else {
            break
        }
    }
    return s.substring(start, end)
}

formatKf(String code): String {
    var out = ""
    var depth = 0
    var line = ""
    var inString = false
    var inLineComment = false
    var inBlockComment = false
    var i = 0
    while (i < code.length()) {
        var c = code.substring(i, i + 1)
        var next2 = code.substring(i, minInt(i + 2, code.length()))
        if (c == "\n") {
            var trimmed = trimLine(line)
            var opens = 0
            var closes = 0
            var j = 0
            while (j < trimmed.length()) {
                var ch = trimmed.substring(j, j + 1)
                if (ch == "{") {
                    opens++
                } else if (ch == "}") {
                    closes++
                }
                j++
            }
            var lineDepth = depth
            if (closes > 0 && opens == 0) {
                lineDepth = depth - closes
                if (lineDepth < 0) {
                    lineDepth = 0
                }
            }
            if (trimmed.length() > 0) {
                out = out + spaces(lineDepth) + trimmed + "\n"
            } else {
                out = out + "\n"
            }
            depth = depth + opens - closes
            if (depth < 0) {
                depth = 0
            }
            line = ""
            inLineComment = false
            i++
            continue
        }
        if (inLineComment) {
            line = line + c
            i++
            continue
        }
        if (inBlockComment) {
            line = line + c
            if (next2 == "*/") {
                line = line + "*"
                i++
                inBlockComment = false
            }
            i++
            continue
        }
        if (inString) {
            line = line + c
            if (c == "\\") {
                i++
                if (i < code.length()) {
                    line = line + code.substring(i, i + 1)
                }
            } else if (c == "\"") {
                inString = false
            }
            i++
            continue
        }
        if (next2 == "//") {
            line = line + "//"
            i = i + 2
            inLineComment = true
            continue
        }
        if (next2 == "/*") {
            line = line + "/*"
            i = i + 2
            inBlockComment = true
            continue
        }
        if (c == "\"") {
            line = line + c
            inString = true
            i++
            continue
        }
        line = line + c
        i++
    }
    var last = trimLine(line)
    if (last.length() > 0) {
        out = out + spaces(depth) + last
    }
    return out
}
